// One event, one letter, one screened booking agent — the active/not-
// suppressed checks, the person-confirmed route, the unspent season and the
// draw-evidence floor all ran upstream, inside the approval transaction.
// This executor either delivers exactly the letter that was approved or
// delivers nothing.
//
// It writes no words of its own. The letter was composed in CrowdRelay and
// travels in `draft`; a payload without one is refused rather than filled
// in, because a letter this executor composed would be one the band never
// read — and the evidence inside an approach payload is what the letter
// already cites, not material for a second letter.
//
// Two event types share this transport:
//  - crowdrelay.booking_agent.approach_requested — the season's application
//  - crowdrelay.booking_agent.reply_requested    — the band's answer to an
//    agent who wrote back (answers_interaction_id). A reply is the same
//    mailbox and the same verbatim rule; the type is separate so an
//    executor that does not know replies skips it rather than mistaking it
//    for a pitch.
const e = $json;
const isApproach = e && e.type === 'crowdrelay.booking_agent.approach_requested';
const isReply = e && e.type === 'crowdrelay.booking_agent.reply_requested';
if (!e || (!isApproach && !isReply) || e.version !== 1) {
  throw new Error('booking-agent refused: unsupported event');
}
const d = e.data ?? {};
const actionId = String(d.action_id || '').trim();
const agentId = String(d.agent_id || '').trim();
const draft = d.draft || {};
const subject = String(draft.subject || '').trim();
const body = String(draft.body || '').trim();
if (!actionId || !agentId) {
  throw new Error('booking-agent refused: payload incomplete');
}
// The refusal that keeps the promise: no approved words, no send. An action
// that lost its letter is refused rather than writing one here on the
// band's behalf — the exact thing this lane exists to prevent.
if (!subject || !body) {
  throw new Error(
    'booking-agent refused: no approved letter in the payload — nothing may compose one here'
  );
}
// One contact, resolved inside the sending lock upstream. The address is
// never shown to the band — neither an application nor a reply can be used
// to harvest it.
const email = String(d.contact_email || '').trim();
if (!email.includes('@')) {
  throw new Error('booking-agent refused: agent without contact_email');
}
return [{ json: {
  event_id: e.id,
  action_id: actionId,
  agent_id: agentId,
  agent_name: String(d.agent_name || ''),
  agency: String(d.agency || ''),
  is_reply: isReply,
  answers_interaction_id: isReply ? Number(d.answers_interaction_id) : null,
  SendTo: email,
  SendSubject: subject.slice(0, 220),
  SendBody: body,
}}];

const claim = $json;
const intent = $('Validate the approved application').first().json;
// A replay of an already-finished action is a no-op, not an error.
if (claim.disposition === 'already_succeeded') return [];
// claimed is the only disposition that may reach the provider; in_flight
// and ambiguous stay claimed upstream and never send twice.
if (claim.disposition !== 'claimed' || !claim.claim_token) {
  throw new Error('Provider execution ' + (claim.disposition || 'unclaimed') + '; fail closed to prevent duplicate external side effects');
}
return [{ json: { ...intent, claim_token: String(claim.claim_token), attempt_number: Number(claim.attempt_number || 1) } }];

const intent = $('Fail-closed claim gate').first().json;
const failed = Boolean($json.error);
const ref = $json.threadId || $json.thread_id || $json.id || null;
return [{ json: {
  action_id: intent.action_id,
  receipt_key: (intent.is_reply ? 'booking_agent_reply' : 'booking_agent_approach') + ':' + intent.action_id + ':email',
  executor_id: $env.CROWDRELAY_EXECUTOR_ID || 'virya-n8n-primary',
  status: failed ? 'failed' : 'succeeded',
  claim_token: intent.claim_token,
  provider_reference: failed ? null : (ref ? String(ref).slice(0, 240) : null),
  error_kind: failed ? 'gmail_send_failed' : null,
  metadata: {
    channel: 'email',
    event_id: intent.event_id,
    agent_id: intent.agent_id,
    agent_name: intent.agent_name,
    agency: intent.agency,
    is_reply: intent.is_reply,
    answers_interaction_id: intent.answers_interaction_id,
  },
  occurred_at: new Date().toISOString(),
}}];
